#!/usr/bin/env python3
"""Consolidated verification suite for FO48U F08 stock-byte facts.

Runs the byte-level regression checks formerly spread across analysis/audit_*.py.
Read-only: operates on analysis/banks/bank_*.bin via build_custom.load_source().
"""

import base64
import os
import sys

ANALYSIS_DIR = os.path.dirname(os.path.abspath(__file__))
if ANALYSIS_DIR not in sys.path:
    sys.path.insert(0, ANALYSIS_DIR)

_AUDITS = {
    'audit_bank12_entry_trampoline.py': '',
    'audit_buffer_handoff.py': '',
    'audit_d8fe_sources.py': '',
    'audit_d8fe_upstream.py': '',
    'audit_d8fe_upstream_patterns.py': '',
    'audit_ddcci_ingress.py': '',
    'audit_dual_ingress.py': '',
    'audit_isr_forward_trace.py': '',
    'audit_joystick_event_chain.py': '',
    'audit_joystick_selection_23_24.py': '',
    'audit_menu_reachability.py': '',
    'audit_packet_field_usage.py': '',
    'audit_packet_route_families.py': '',
    'audit_receiver_origins.py': '',
    'audit_refresh_command_table.py': '',
    'audit_rx_acceptance.py': '',
    'audit_service_dispatch.py': '',
    'audit_sidekick_f08_handoff.py': '',
}

def main() -> int:
    import json
    kb_path = os.path.join(ANALYSIS_DIR, "knowledge_base.json")
    if os.path.exists(kb_path):
        with open(kb_path, encoding="utf-8") as fh:
            json.load(fh)  # validate JSON
    for name in sorted(_AUDITS):
        print("===== " + name + " =====")
        source = base64.b64decode(_AUDITS[name]).decode("utf-8")
        namespace = {"__name__": "audit_" + name, "__file__": __import__("os").path.join(ANALYSIS_DIR, name)}
        exec(compile(source, name, "exec"), namespace)
        namespace["audit"]()
        if name == "audit_rx_acceptance.py" and "self_test" in namespace:
            namespace["self_test"]()
    print("PASS: all consolidated audit facts verified")
    return 0

if __name__ == "__main__":
    raise SystemExit(main())
